"""Heat diffusion on the GPU.

Usage: uv run main.py <grid-file>

The grid file holds "<width> <height> <steps>" followed by height rows of
width whole numbers. Each step replaces every cell with
(4 * self + left + right + up + down) // 8, computed by a WGSL compute kernel
from the previous step's values. Out-of-grid neighbours clamp to the edge.
"""

import struct
import sys

import wgpu

WORKGROUP = 16

SHADER = """
struct Params {
    width: u32,
    height: u32,
    pad0: u32,
    pad1: u32,
};

@group(0) @binding(0) var<uniform> p: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(%d, %d)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let x = gid.x;
    let y = gid.y;
    if (x >= p.width || y >= p.height) {
        return;
    }
    let xl = select(x - 1u, 0u, x == 0u);
    let xr = min(x + 1u, p.width - 1u);
    let yu = select(y - 1u, 0u, y == 0u);
    let yd = min(y + 1u, p.height - 1u);

    let row = y * p.width;
    let self_v = src[row + x];
    let left = src[row + xl];
    let right = src[row + xr];
    let up = src[yu * p.width + x];
    let down = src[yd * p.width + x];

    dst[row + x] = (4u * self_v + left + right + up + down) / 8u;
}
""" % (WORKGROUP, WORKGROUP)


def read_grid(path):
    with open(path) as f:
        tokens = f.read().split()
    width, height, steps = int(tokens[0]), int(tokens[1]), int(tokens[2])
    cells = [int(t) for t in tokens[3 : 3 + width * height]]
    return width, height, steps, cells


def diffuse(width, height, steps, cells):
    """Run `steps` diffusion steps on the GPU and return the final cells."""
    device = wgpu.gpu.request_adapter_sync(
        power_preference="high-performance"
    ).request_device_sync()

    size = width * height * 4
    usage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC | wgpu.BufferUsage.COPY_DST
    buf_a = device.create_buffer(size=size, usage=usage)
    buf_b = device.create_buffer(size=size, usage=usage)
    device.queue.write_buffer(buf_a, 0, struct.pack("<%dI" % len(cells), *cells))

    params = device.create_buffer_with_data(
        data=struct.pack("<4I", width, height, 0, 0),
        usage=wgpu.BufferUsage.UNIFORM,
    )

    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto",
        compute={"module": module, "entry_point": "main"},
    )
    layout = pipeline.get_bind_group_layout(0)

    def bind(src, dst):
        return device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": params, "offset": 0, "size": 16}},
                {"binding": 1, "resource": {"buffer": src, "offset": 0, "size": size}},
                {"binding": 2, "resource": {"buffer": dst, "offset": 0, "size": size}},
            ],
        )

    # Step n reads from `src` and writes `dst`; the roles swap every step.
    groups = [bind(buf_a, buf_b), bind(buf_b, buf_a)]

    encoder = device.create_command_encoder()
    for step in range(steps):
        compute = encoder.begin_compute_pass()
        compute.set_pipeline(pipeline)
        compute.set_bind_group(0, groups[step % 2])
        compute.dispatch_workgroups(
            (width + WORKGROUP - 1) // WORKGROUP,
            (height + WORKGROUP - 1) // WORKGROUP,
        )
        compute.end()

    final = buf_a if steps % 2 == 0 else buf_b
    readback = device.create_buffer(size=size, usage=wgpu.BufferUsage.MAP_READ | wgpu.BufferUsage.COPY_DST)
    encoder.copy_buffer_to_buffer(final, 0, readback, 0, size)
    device.queue.submit([encoder.finish()])

    readback.map_sync(wgpu.MapMode.READ)
    data = readback.read_mapped()
    result = list(struct.unpack("<%dI" % (width * height), bytes(data)))
    readback.unmap()
    return result


def main(argv):
    if len(argv) < 2:
        sys.stderr.write("usage: main.py <grid-file>\n")
        return 2

    width, height, steps, cells = read_grid(argv[1])
    if steps > 0:
        cells = diffuse(width, height, steps, cells)

    lines = []
    total = 0
    for row in range(height):
        values = cells[row * width : (row + 1) * width]
        total += sum(values)
        lines.append(" ".join(map(str, values)))
    lines.append("SUM %d" % total)
    sys.stdout.write("\n".join(lines) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

